 "content": "def transform(grid):
    """Extend a colored motif along an adjoining run of 5 guide cells."""
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])

    def runs(line):
        found = []
        i = 0
        while i < len(line):
            if line[i] != 5:
                i += 1
                continue
            j = i + 1
            while j < len(line) and line[j] == 5:
                j += 1
            if j - i >= 2:
                found.append((i, j - 1))
            i = j
        return found

    # A vertical 5-run carries the adjacent motif at its lower end; repeat
    # that motif upward/downward over the full guide.
    for c in range(w):
        for top, bottom in runs([src[r][c] for r in range(h)]):
            for side in (-1, 1):
                first_c = c + side
                if not (0 <= first_c < w) or src[bottom][first_c] in (0, 5):
                    continue
                # Source motif is bottom-aligned with the guide endpoint.
                top_src = bottom
                while top_src > 0 and src[top_src - 1][first_c] not in (0, 5):
                    top_src -= 1
                motif_h = bottom - top_src + 1
                width_src = 0
                for cc in range(first_c, w if side > 0 else -1, side):
                    if src[bottom][cc] in (0, 5):
                        break
                    width_src += 1
                if width_src == 0:
                    continue
                # Keep only columns present throughout the motif rows.
                while width_src > 0 and any(
                    src[rr][first_c + side * (width_src - 1)] in (0, 5)
                    for rr in range(top_src, bottom + 1)
                ):
                    width_src -= 1
                if width_src == 0:
                    continue
                for r in range(top, bottom + 1):
                    motif_row = top_src + ((r - top_src) % motif_h)
                    for k in range(width_src):
                        cc = first_c + side * k
                        if src[r][cc] == 0:
                            out[r][cc] = src[motif_row][cc]

    # A horizontal 5-run carries a perpendicular strip attached below or
    # above one endpoint; repeat that strip across the guide.
    for r in range(h):
        for left, right in runs(src[r]):
            for endpoint in (left, right):
                for side in (-1, 1):
                    first_r = r + side
                    if not (0 <= first_r < h) or src[first_r][endpoint] in (0, 5):
                        continue
                    motif_h = 0
                    rr = first_r
                    while 0 <= rr < h and src[rr][endpoint] not in (0, 5):
                        motif_h += 1
                        rr += side
                    for c in range(left, right + 1):
                        for k in range(motif_h):
                            rr = first_r + side * k
                            if src[rr][c] == 0:
                                out[rr][c] = src[rr][endpoint]
    return out
